"use client";

import { useState, useRef, useEffect } from "react";
import { AnimatePresence, motion } from "framer-motion";

// ─── Types ────────────────────────────────────────────────────────────────────

type Phase =
  | "landing"
  | "workspace"
  | "upload"
  | "ingesting"
  | "map"
  | "insight"
  | "intelligence";

type ContractType = "employment" | "rental" | "freelance" | "service" | "other";

interface AnalyzedContract {
  id: string;
  name: string;
  type: ContractType;
